<div class="page-heading"><h1>Controle PCM / Curva S</h1><?= $this->Html->link('Configurar calendário, pesos e metas',['action'=>'configuracao','?'=>['entressafra_id'=>$season]],['class'=>'btn btn-outline-primary']) ?></div>
<section class="panel"><?= $this->element('evolucao_filters') ?>
<?= $this->Form->create(null,['type'=>'get','class'=>'row g-3']) ?><?php foreach($this->request->getQueryParams() as $k=>$v): if(is_scalar($v)&&!in_array($k,['pesos','metas','registrado_ate'],true)): ?><?= $this->Form->hidden($k,['value'=>$v]) ?><?php endif; endforeach; ?><?= $this->Form->hidden('entressafra_id',['value'=>$season]) ?>
<?php foreach(['pesos'=>$weightVersions,'metas'=>$planVersions] as $name=>$versions): $opts=[]; foreach($versions as $v){if($v['aprovado_em'] && !($name==='metas' && $hasScopedCalendars))$opts[$v['id']]='#'.$v['id'].' '.$v['nome'];} ?><div class="col-md-4"><?= $this->Form->control($name,['label'=>'Versão oficial de '.$name,'options'=>$opts,'empty'=>'Última aprovada no corte','value'=>$this->request->getQuery($name),'class'=>'form-select']) ?></div><?php endforeach; ?>
<div class="col-md-4"><?= $this->Form->control('registrado_ate',['type'=>'datetime-local','label'=>'Reproduzir registros conhecidos até (São Paulo)','value'=>$this->request->getQuery('registrado_ate'),'class'=>'form-control']) ?></div><?= $this->Form->button('Reproduzir histórico',['class'=>'btn btn-outline-primary']) ?><?= $this->Form->end() ?>
<?php if($long): ?><div class="alert alert-warning mt-3"><?= $long ?> apontamento(s) com duração superior a 24 horas. Confira datas de início e fim; nenhum registro foi alterado.<ul><?php foreach($longRows as $entry): ?><li><?= $this->Html->link('Apontamento #'.$entry->id,['controller'=>'Apontamentos','action'=>'view',$entry->id]) ?> · <?= h($entry->inicio->setTimezone('America/Sao_Paulo')->format('d/m/Y H:i')) ?> até <?= h($entry->fim->setTimezone('America/Sao_Paulo')->format('d/m/Y H:i')) ?> · <?= h(round($entry->minutos/60,2)) ?> horas</li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if(!$report['weight'] || $report['realizado']===null): ?><div class="alert alert-warning mt-3">Pesos oficiais pendentes. A evolução física simples (não ponderada) continua disponível abaixo.</div><?php endif; ?>
<?php if(!$report['escopo_completo'] && !$hasScopedCalendars): ?><p class="text-secondary mt-3">Recorte por setor, caderno ou O.S.: realizado normalizado pelos pesos das O.S. deste recorte. A programação oficial aplica-se à entressafra completa e não é atribuída automaticamente ao recorte.</p><?php endif; ?>
</section>
<div class="row g-3 my-3"><?php foreach(['total'=>'Total de O.S.','sem_inicio'=>'Sem início físico','andamento'=>'Em andamento','concluidas'=>'Fisicamente concluídas','pendentes'=>'Sem atualização na semana'] as $key=>$label): ?><div class="col-6 col-lg"><div class="panel h-100"><small><?= h($label) ?></small><strong class="d-block fs-3"><?= $report['counts'][$key] ?></strong></div></div><?php endforeach; ?></div>
<div class="row g-3 my-3"><?php foreach(['simple'=>'Evolução física simples (não ponderada)','programado'=>'Programado oficial','realizado'=>'Realizado ponderado oficial','desvio'=>'Desvio ponderado (p.p.)','variacao'=>'Evolução ponderada semanal (p.p.)'] as $key=>$label): ?><div class="col-md-3"><div class="panel"><small><?= h($label) ?></small><strong class="d-block fs-4"><?= h(in_array($key,['desvio','variacao'],true)&&$report[$key]!==null?number_format($report[$key],2,',','.').' p.p.':$fmt($report[$key])) ?></strong></div></div><?php endforeach; ?></div>
<p><?= $remaining ?> dias até o fim da entressafra. Referência <?= h($reference) ?>. Pesos: #<?= h($report['weight']['id']??'pendente') ?>; programação: <?= $hasScopedCalendars?'por áreas/prazos (use o corte histórico)':('#'.h($report['plan']['id']??'pendente')) ?>.</p>
<p class="text-secondary">“Sem atualização na semana” é um indicador informativo e pode incluir O.S. sem início, em andamento ou concluídas. Não bloqueia lançamentos nem o cálculo da Curva S; o último acumulado é mantido, ou 0% quando nunca houve lançamento.</p>
<p><strong>Indicador não ponderado:</strong> <?= $report['counts']['concluidas'] ?> de <?= $report['counts']['total'] ?> O.S. fisicamente concluídas (<?= number_format($report['counts']['total']?$report['counts']['concluidas']/$report['counts']['total']*100:0,2,',','.') ?>%). Esta proporção de O.S. não representa a Curva S ponderada oficial.</p>
<section class="panel mb-4"><h2>Consolidação por setor e caderno</h2><p>Cada grupo usa a soma dos pesos de suas O.S. únicas como denominador; o total da entressafra é calculado diretamente pelas O.S., sem somar os percentuais dos grupos.</p><div class="table-responsive"><table class="table"><thead><tr><th>Grupo</th><th>Nome</th><th>O.S.</th><th>Soma dos pesos</th><th>Realizado ponderado</th><th>Evolução simples (não ponderada)</th><th>Situação física (não ponderada)</th></tr></thead><tbody><?php foreach($report['groups'] as $type=>$groups): foreach($groups as $g): ?><tr><td><?= h($type) ?></td><td><?= h($g['nome']) ?></td><td><?= $g['quantidade'] ?></td><td><?= h($g['soma_pesos']) ?></td><td><?= h($fmt($g['realizado'])) ?></td><td><?= h($fmt($g['simples'])) ?></td><td><?php $zero=count(array_filter($g['valores'],fn($v)=>$v==0));$done=count(array_filter($g['valores'],fn($v)=>$v==100)); ?><?= $zero ?> sem início · <?= $g['quantidade']-$zero-$done ?> em andamento · <?= $done ?> concluídas (<?= number_format($done/$g['quantidade']*100,2,',','.') ?>% das O.S.)</td></tr><?php endforeach; endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Evolução por <?= h($this->request->getQuery('setor_id') ? ($sectors->toArray()[(int)$this->request->getQuery('setor_id')]??'setor') : 'entressafra') ?></h2><p><strong>Evolução física simples (não ponderada): <?= h($fmt($report['simple'])) ?></strong>. Média dos percentuais acumulados das O.S. únicas do filtro; O.S. sem lançamento contam como 0%. Não representa a Curva S ponderada oficial.</p><?php if($report['programado']===null): ?><p class="text-secondary">Programação pendente</p><?php endif; ?><p>Programado oficial: azul · Realizado ponderado: verde · Evolução simples não ponderada: roxo · Tendência ponderada estimada: laranja tracejado. A estimativa usa a variação dos últimos registros semanais disponíveis (até quatro referências); não substitui a meta oficial.</p>
<?php $points=$report['points']; $n=count($points); $path=function($key)use($points,$n){$p=[];foreach($points as $i=>$v){if($v[$key]!==null)$p[]=(40+($n>1?$i/($n-1):0)*860).','. (270-$v[$key]*2.4);}return implode(' ',$p);}; ?>
<svg viewBox="0 0 940 320" role="img" aria-label="Evolução física simples, Curva S ponderada e programação oficial" style="width:100%;height:auto;max-height:440px">
<?php foreach([0,25,50,75,100] as $v): ?><line x1="40" x2="900" y1="<?= 270-$v*2.4 ?>" y2="<?= 270-$v*2.4 ?>" stroke="#dce3e6"/><text x="2" y="<?= 275-$v*2.4 ?>" font-size="12"><?= $v ?>%</text><?php endforeach; ?>
<?php foreach(['programado'=>'#2369b3','realizado'=>'#148356','simples'=>'#7952b3','tendencia'=>'#cc7420'] as $k=>$color): ?><polyline points="<?= h($path($k)) ?>" fill="none" stroke="<?= $color ?>" stroke-width="3" <?= $k==='tendencia'?'stroke-dasharray="8 5"':'' ?> /><?php endforeach; ?>
<text x="40" y="305" font-size="12"><?= h($points[0]['referencia']??'') ?></text><text x="810" y="305" font-size="12"><?= h($n?$points[$n-1]['referencia']:'') ?></text></svg>
<details><summary>Valores do gráfico / histórico semanal</summary><div class="table-responsive"><table class="table"><thead><tr><th>Referência</th><th>Programado</th><th>Realizado</th><th>Evolução simples (não ponderada)</th><th>Tendência estimada</th></tr></thead><tbody><?php foreach($points as $p): ?><tr><td><?= h($p['referencia']) ?></td><?php foreach(['programado','realizado','simples','tendencia'] as $k): ?><td><?= h($fmt($p[$k])) ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></details></section>
<section class="panel mt-4"><h2>Detalhamento por O.S.</h2><div class="table-responsive"><table class="table"><thead><tr><th>O.S.</th><th>Serviço / equipamento</th><th>Setor / caderno</th><th>Peso</th><th>Acumulado</th><th>Prazo físico / programado</th><th>Situação da semana</th></tr></thead><tbody><?php foreach($report['details'] as $a): ?><tr><td><?= $this->Html->link($a['os_numero'],['action'=>'historico',$a['id']]) ?></td><td><?= h(\App\Service\OsApresentacao::record($a)['descricao']) ?><br><?= h($a['bem']) ?></td><td><?= h(\App\Service\OsApresentacao::record($a)['setor_apresentacao']) ?> / <?= h($a['caderno_nome']) ?></td><td><?= h($a['peso']??'Pendente') ?></td><td><?= h($fmt($a['estado']['percentual'])) ?></td><td><?= h($a['prazo']??'Classificação pendente') ?><br><?= h($fmt($a['programado_individual'])) ?></td><td><?= $a['estado']['pendente']?'Sem atualização na semana':'Verificada na semana' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
